def calculate_triangle_area(p1, p2, p3):
    """Calculate the area of a triangle given the coordinates of its vertices."""
    return abs((p1[0]*(p2[1]-p3[1]) + p2[0]*(p3[1]-p1[1]) + p3[0]*(p1[1]-p2[1])) / 2.0)

def sort_coordinates(cities):
    """Sort cities by their x-coordinates and then by y-coordinates."""
    return sorted(cities, key=lambda x: (x[0], x[1]))

def find_triangle(cities):
    """Find a set of three cities that form a triangle with a given area."""
    area = 0
    for i in range(len(cities)):
        for j in range(i+1, len(cities)):
            for k in range(j+1, len(cities)):
                area_temp = calculate_triangle_area(cities[i], cities[j], cities[k])
                if abs(area_temp - area) < 1e-9 and area_temp > 0:
                    area = area_temp
                    answer = sorted((cities[i], cities[j], cities[k]))
                    return answer

    return None

