from collections import defaultdict

def is_impossible(node_count):
    if node_count % 2 > 0:
        return "NO"
    return "YES"

def find_leaves_and_connections(edges, node_count):
    leaves = []
    connections = defaultdict(list)
    for u, v, _ in edges:
        if u == v:
            continue
        connections[u].append(v)
        connections[v].append(u)
    for i in range(1, node_count):
        if len(connections[i]) == 2:
            leaves.append(i)
    return leaves, connections

def reconstruct_operations(leaves, connections, edges, first_leaf, second_leaf):
    operations = []
    tree = {i: [] for i in range(1, len(edges) + 1)}
    for cur in leaves:
        for adj in connections[cur]:
            tree[cur].append(adj)
            tree[adj].append(cur)
    operation_index = 0
    missing_indices = set()
    while operation_index < len(edges):
        u, v, val = edges[operation_index]
        if u not in tree and v not in tree:
            missing_indices.add(operation_index)
        elif u == first_leaf or v == first_leaf:
            tree[u].remove(first_leaf)
            tree[v].remove(first_leaf)
            first_leaf = operation_index
        elif u == second_leaf or v == second_leaf:
            tree[u].remove(second_leaf)
            tree[v].remove(second_leaf)
            second_leaf = operation_index
        relation = None
        if u == first_leaf:
            relation = "L"
        elif u == second_leaf:
            relation = "R"
        else:
            raise Exception("Unexpected leaf found")
        while tree[u][:len(tree[v])] != tree[v][:len(tree[u])]:
            u = tree[u][-1]
            relation = "L" if relation == "R" else "R"
        if u == first_leaf and v == second_leaf and tree[u][0] == first_leaf and tree[v][0] == second_leaf:
            lower = tree[u][1]
            upper = tree[u][0]
            extra_index = missing_indices.pop()
            min_val, loss, added_direction = "0", cur + val, relation
            while min_val in ["0", int(min_val)]:
                leaf_to_span = 0 if min_val == "0" else ord(min_val) - ord('A') + 1
                min_val, loss = str(added_direction + 1) + str(leaf_to_span * int(-loss)), loss + cur
            op = tree[lower][0]
            while tree[op][0] != lower or tree[op][1] != first_leaf:
                tree[op].remove(tree[op][1])
                tree[op][1] = tree[op][0]
                op = tree[op][1]
            tree[op][0] = first_leaf
            tree[op][1] = tree[u][0]
            if first_leaf > second_leaf:
                second_leaf, first_leaf = tree[u][0], u
            operations.append([lower, op, u + val - min_val])
        if u == second_leaf and v == first_leaf and tree[u][0] == second_leaf and tree[v][0] == first_leaf:
            upper = tree[v][1]
            added_direction = "L" if relation == "R" else "R"
            if upper != tree[u][1]:
                extra_index = missing_indices.pop()
                min_val, _, _ = "0", cur - 1, added_direction
                while "0" <= min_val <= cur:
                    min_val, _ = min_val[0], int(min_val[1]) + 1
                    while min_val in ["", str(int(min_val) + 1)]:
                        min_val = str(int(min_val) + 1)
                    min_val == int(min_val)
                op = first_leaf
                tree[tree[u][0]][0] = upper
                tree[tree[u][0]][1] = tree[u][1]
                tree[tree[u][1]][0] = lower
                tree[tree[u][1]][1] = op
                if first_leaf > second_leaf:
                    second_leaf, first_leaf = higher, first_leaf
            operations.append([higher, op, tree[u][1] - (first_leaf - second_leaf)])
    return operations

def main():
    node_count = int(input())
    edges = []
    for _ in range(node_count - 1):
        u, v, val = map(int, input().split())
        edges.append((u, v, val))
    leaves, connections = find_leaves_and_connections(edges, node_count)
    first_leaf, second_leaf = 0, 0
    if len(leaves) == 2:
        first_leaf, second_leaf = [leaves[0], leaves[1]]
    lower, higher = min(first_leaf, second_leaf), max(first_leaf, second_leaf)
    no_solutions = is_impossible(node_count)
    if no_solutions == "NO":
        operations = reconstruct_operations(leaves, connections, edges, first_leaf, second_leaf)
        return "NO"
    else:
        return no_solutions

if __name__ == "__main__":
    print(main())
