    def dfs(index, next_index):
        if graph_visited[index]:
            print(-1)
            return
        graph_visited[index] = True
        for next in cycle_map[index]:
            dfs(next, next_index)
        next_index, cycle_size = next_index, len(cycle_map[next_index])

        for val in leftovers:
            vals = [x + 1 for x in cycle_map[val] + [val]]
            for i, val in enumerate(vals):
                if not graph[index][0]:
                    graph[index][0] = next(i, i + 1, vals[val])
                else:
                    graph[next][graph[i][0]] = vals[val]

        leftovers += [i for i in range(n) if graph[i][0] == cycle_size and not graph_visited[i]]

        return(True)

