def generate_sequence(k):
    if k > 50:
        return "-1"
    a = [0] * k  # Initialize sequence with zeros
    c = [0] * k  # Initialize coefficients with zeros
    for i in range(1, k + 1):
        if i == 1 or i == 2:
            c[i-1] = 1
        elif i == k:
            c[i-1] = 1
        elif i == k - 1:
            c[i-1] = 1
        else:
            c[i-1] = min(c[i-1], c[i-1] + c[i-1 - k % i])
        if c[i-1] == 1:
