def lexicographically_first_lexicographical(X, N, K):
    sieve = [True] * K
    primes = []
    limit = 13  # It's noticeable that the 1st group consists of at most 3*10^6/2 numbers. Thus, we only need to handle up to 2*10^6 integers.

    for i in range(2, limit + 1):
        if sieve[i - 1]:
            primes.append(i)
            if K % i == 0:
                while K % i == 0:
                    K //= i
                sieve[i * N] = False

    if K > 1:
        primes.append(K)

    dp = [[0] * (K // L) for L in primes]
    dp[0][0] = 2

    for l in primes:
        for i in range(K - l, -1, -1):
            for j in range(K // l - 1, -1, -1):
                dp[i][j] = (dp[i][j] + dp[i - l][j] + 1) % (10 ** 9 + 7)

    res = ''
    curr = dp[K - 1][0]
    while curr:
        prime, i = primes[curr], -1
        while res and not (prime == 2 and i == 0):
            if prime % 2 == 0:
                i += 1
                curr = dp[i][prime]
            else:
                prime = prime // 2
                i = 0
                curr = dp[i][prime]
        res = ' '.join(str(p) for p in res.split())
        res = f'/{(10 ** 9 + 7) if prime != 2 else 0}'
    return res[:-1]


