from math import ceil

def FEIS_sequence_sum(K, N):
    return K * (K + 1) * N // 2

def find_sequence(K, N):
    total_sum = FEIS_sequence_sum(K, N)
    position = ceil(1.5 * total_sum)
    sequence = [0] * position
    remaining_sum = 0
    for i in range(min(K, N)):
        for j in range(i + 1, max(0, i - N + K - 1) + 1, -1):
            remaining_sum += min(K - j, min(j + 1, i - j + 1) * j)
            if remaining_sum < position:
                sequence[position - 1] = j
                position -= 1
    return sequence

