def mod_pow_modulo(m, n, mod):
    result = 1
    m = m % mod
    while n > 0:
        if n % 2 != 0:
            result = (result * m) % mod
        n = n // 2
        m = (m * m) % mod
    return result % mod

def count_multisets(A0, A1, A2, A3, S, MOD=1000000007):
    base = [1, A1, A2, A3]
    ans = 0
    for i in range(2, S + 1):
        if i >= A0 + A1 + A2 + A3:
            ans = (ans + sum(base) * mod_pow_modulo(2, i - (A0 + A1 + A2 + A3) + 1, MOD) * mod_pow_modulo(2, A2, MOD)) % MOD
        else:
            count = (i - A3) * mod_pow_modulo(2, A1, MOD) % MOD
            for j in range(A2 + A3):
                count = (count + mod_pow_modulo(2, i - A2 - A3, MOD) // A2) % MOD
            ans = (ans + count) % MOD
    return ans

