def apply_operations(graph, ops):
    root = None
    for node, edges in graph.items():
        if len(edges) == 1:
            root = node
            break
    if root == None or root not in graph:
        return "NO"

    leaves = find_leaves(graph)
    graph[leaves[0]] = graph[leaves[1]]

    root = leaves[0]
    new_operations = []
    for i in range(len(ops)):
        op = ops[i]
        u, v, immut = op
        while root in graph:
            u = graph[root].pop()
            if immut:
                graph[u].remove(v)
            else:
                graph[u].remove(immut)
            root = graph[root].pop()
        if root == u:
            immut -= u
        elif root == immut:
            immut += u
        elif root == v:
            immut += u
            immut -= v
        else:
            immut -= v
        new_operations.append((u, v, immut))
        ops[i] = (root, immut)
    for u in leaves:
        if not graph[u]:
            graph[u] = leaves
            if u not in graph:
                leaf_index = leaves.index(u)
                leaves[leaf_index] = graph[u]
    return "YES" , len(new_operations), [' '.join(map(str, op)) for op in new_operations]

