import sys

def is_triangle_possible(n, S, cities):
    if n != 3:
        return ('No', [])

    Xs, Ys = zip(*cities)
    S_total = sum(abs((Xs[i] - Xs[(i+1) % 3]) * (Ys[i] - Ys[(i+1) % 3])) for i in range(3))

    # Check if the triangle area condition is satisfied
    if 2 * S_total - S != S_total * S:
        return ('No', [])

    # Check if the point is between the other two points
    for (x,y) in cities:
        if abs((x - x1) * (y - y2) - (x - x2) * (y - y1)) <= S and abs((x - x2) * (y - y3) - (x - x3) * (y - y2)) <= S and abs((x - x3) * (y - y1) - (x - x1) * (y - y3)) <= S:
            return ('Yes', [(x1, y1), (x2, y2), (x3, y3)])

    return ('No', [])

