from typing import List
from itertools import pairwise

def diam_tree(n: int, edges: List[List[int]]) -> int:
    tree = [[] for _ in range(n)]
    for u, v in edges:
        tree[u-1].append(v-1)
        tree[v-1].append(u-1)

    def dfs(node: int, parent: int, height: int):
        if node == 0:
            children = {None}
        else:
            children = set()
            for neighbor in tree[node]:
                if neighbor != parent:
                    children.add(neighbor)
        distances = {c: height for c in children}
        max_dist = height + 1
        for c in children:
            new_height = max([distances[neighbor] for neighbor in tree[c] if neighbor != parent])
            distances[c] = new_height
            max_dist = max(max_dist, new_height)
            if distances[c] > 0:
                dfs(c, node, distances[c])
        return max_dist

    max_dist = 0
    for node in range(n):
        distances = {}
        dfs(node, -1, 0)
        max_dist = max(max_dist, max(map(lambda x: distances[x], tree[node])))
    return sum(max_dist + i for i in range(1, n+1))

