def generate_functional_graph():
    graph = [-1] * 301  # Initialize graph with -1 to indicate unknown values

    n = int(input().strip())
    for _ in range(n):
        inputs = input().strip().split()
        precycle = int(inputs[0])
        cycle = int(inputs[1])

        if precycle == 0 and cycle != 1:
            graph[cycle] = 'not-formed'
            return graph

        elif precycle == 0 and cycle == 1:
            pass  # Already set graph to filled already when cycle=1

        elif precycle > 0:
            if graph[precycle] == 'not-formed':
                graph[precycle] = 'not-formed'
                return graph

            cycles = [cycle]
            while graph[cycles[-1]] != 'not-formed':
                cycles.append(graph[cycles[-1]])

            max_freq = 0
            best_precycle = None

            for i in range(precycle - 1, len(cycles) - 1):
                if graph[i] != 'not-formed' and graph[i] not in cycles:
                    if cycles.count(graph[i]) > max_freq:
                        max_freq = cycles.count(graph[i])
                        best_precycle = i
            graph[precycle] = best_precycle

        elif precycle == 0 and cycle != 0:
            graph[0] = cycle
            graph[cycle] = 0

    return graph

def print_graph(graph):
    print(' '.join(map(str, graph)))

if __name__ == "__main__":
    graph = generate_functional_graph()
    print_graph(graph)
