def detect_error(vertex, tree):
    """
    Returns True if the questions mark for vertex should be replaced with a number
    that would create a functional graph matching the given tree structure.
    Otherwise, returns False and the value to be replaced.
    """
    # Extract information from the vertex pair
    ex_to_child, cycle_length = tree[vertex]
    child_to_ex = tree.keys() - {vertex}

    # Calculate differences
    to_child_diff = ex_to_child - cycle_length
    from_child_diff = cycle_length - ex_to_child

    # Add differences to the children' ex-to-child pairs
    for child in child_to_ex:
        ex_from_child, cycle_from_child = tree[child]
        tree[child] = (ex_from_child + to_child_diff, cycle_from_child)

    # Check against possible fixed values
    coords_booked = frozenset({
        ex_to_child, cycle_length,
        ex_from_child + to_child_diff, ex_from_child - to_child_diff,
        cycle_length - ex_from_child, cycle_length + ex_from_child
    })

    for possible_value in coords_booked:
        if possible_value == cycle_length - ex_from_child or possible_value == cycle_length + ex_from_child:
            return True, 0 if possible_value == cycle_length else 1
        if possible_value == cycle_from_child - ex_to_child or possible_value == cycle_from_child + ex_to_child:
