import sys

def getMax(length, nMin, nMax, permutation, size):
    maxGlobal = -10000000000
    maxIndex = -1

    for i in range(length):
        sum = 0
        for j in range(i, length):
            sum += permutation[j] 
        if sum >= maxGlobal and nMin <= size - i <= nMax and size - i >= maxGlobal:
            maxGlobal = sum
            maxIndex = i

    return maxIndex

def getSequence(length, nMin, nMax, currentSize, permutation):
    while currentSize < length:
        permHash = 0
        for i in range(len(permutation)):
            permHash += permutation[i] * ((10 + i) ** currentSize)

        if permHash in permutation:
            currentSize += 1
        else:
            permutation.append(permHash)

    return permutation[length - 1:]

def solve(k, n):
    sizes = (2 ** (n+1) - 1) * len(range(1, k + 1)) // n + 1
    sizeDictList = []
    sizeDictList.append({0: 0})

    currentSize = 1
    permutation = [0]
    sizeDictList.append({0})

    for maxIndex in range(1, k+1):
        newLength = getMax(maxIndex, 1, n, permutation, currentSize)
        for i in range(len(permutation), newLength):
            st = getSequence(newLength, 1, n, currentSize, permutation)
            sizeDictList.append({updateSet: st, sizeDictList[i]})

            currentSize += 1
            i = newLength

def updateSet(currentSet, newElement):   
    for key in currentSet:
        if key == newElement:
            return currentSet[key] + [newElement]
    currentSet[newElement] = newElement
    return currentSet

