def generate_long_sequence(k):
    if k % 2 == 0:
        return "-1"

    prefix_sum = 1
    while prefix_sum != k:
        prefix_sum *= 2

    values = [1] * k
    prefix_sum -= 1

    for _ in range(prefix_sum):
        values.append(1)

    for _ in range(prefix_sum - 1):
        values.pop()
        values.insert(1, 1)

    for i in range(k):
        values[i] %= 2

