import heapq

def find_xth_smallest_sequence(K, N):
    # Calculate the total number of sequences (X)
    def count_sequences(n1, k1, n2, k2):
        count = 0
        for i in range(n1 + 1):
            for j in range(k1):
                if i + j > n2 or (i + j <= n2 and (i + j + 1 == n2 or i + j + 1 >= n2)):
                    break
                if i <= n2 - j:
                    count += 1
        return count

    def generate_sequences(n1, k1, n2, k2):
        sequences = []
        for i in range(n1 + 1):
            for j in range(max(k1, n2 - n1 + i), min(k1, n2) + 1):
                num = i + j
                if num in (n1, n2):
                    sequences.extend(((i,), (j,),) + tuple(str(1) if num == n1 else ' ' for _ in range(k2 - j)))
                elif num == n2 - 1 and i == n1:
                    sequences.append(tuple(str(1) for _ in range(k1)))
        return sequences

    def concatenate_sequences(sequences):
        combination = []
        for seq in sequences:
            combination.append(' '.join(seq))
        return combination

    def lexicographically_smallest(sequences):
        min_seq = min(sequences)
        return ' '.join(min_seq)

    sequences = generate_sequences(N, K, N, K)
    X = count_sequences(N, K, N, K)
    while len(sequences) > X // 2:
        sequences = concatenate_sequences(sequences)
        X -= count_sequences(N, K, N, K)
        sequences = sequences[:X // 2]

    return lexicographically_smallest(sequences)

