def f(N, A):
    """Evaluate the coefficient A of F(N)"""
    if N == 0:
        return A[0]
    elif N == 1:
        return A[1]
    elif N == 2:
        return A[2]
    else:
        return A[0] + A[1] * N + A[2] * N ** 2

def count_multisets(S, A0, A1, A2, A3):
    """Count the number of distinct multisets of rang values that sum to S"""
    mod = 1000000007
    res = 0

    for i in range(1, S + 1):
        for j in range(1, S + 1):
            for k in range(1, S + 1):
                remaining = S - (i + j + k)
                if remaining >= 0:
                    C1 = f(i, [A0, A1, A2, A3])
                    C2 = f(j, [A0, A1, A2, A3])
                    C3 = f(k, [A0, A1, A2, A3])
                    res += (C1 * C2 * C3) % mod
    return res % mod

