        dic[(a, c)].append(d)
        if (c, b) not in dic:
            dic[(c, b)] = []
        dic[(c, b)].append(d)
        if (c, d) not in dic:
            dic[(c, d)] = []
        dic[(c, d)].append(d)
    return dic

