def find_luck_pairs(lucky_string):
    digits = [char for char in lucky_string]
    string_length = len(digits)

    lr_pairs = [(lr_count(i), i) for i in range(0, string_length - 1) if digits[i] == '4' and digits[i + 1] == '7']
    if lr_pairs:
        return len(lr_pairs)
    return -1

def erase_pairs(s, pairs):
    current_s = s
    for pair, from_index in pairs:
        for k in range(pair):
            current_s = current_s[:from_index - k - 1] + current_s[from_index + k + 1:]
    return current_s

